INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (8, 'hue-sync-box-hdmi-no-signal', 5, 1, 3, 'HDMI no signal / écran noir', 2, '15–30 min', '10–40 €', 0, 'Hue Sync Box : écran noir ou « No signal »', 'Hue Sync Box : écran noir ou « No signal »', 'Hue Sync Box : écran noir ou « No signal »', 'Hue Sync Box : écran noir ou « No signal »', 'Hue Sync Box : écran noir ou « No signal »', 'La TV n’affiche rien lorsque la Sync Box est dans la chaîne HDMI, alors que la source fonctionne en direct.', 'La TV n’affiche rien lorsque la Sync Box est dans la chaîne HDMI, alors que la source fonctionne en direct.', 'La TV n’affiche rien lorsque la Sync Box est dans la chaîne HDMI, alors que la source fonctionne en direct.', 'La TV n’affiche rien lorsque la Sync Box est dans la chaîne HDMI, alors que la source fonctionne en direct.', 'La TV n’affiche rien lorsque la Sync Box est dans la chaîne HDMI, alors que la source fonctionne en direct.', 'Causes fréquentes : Câble HDMI défectueux, ordre de boot TV/box/console, HDCP 2.2 non respecté, ou mode Dolby Vision qui passe en tunnel incompatible.\n\n1. Testez la source → TV sans Sync Box.\n2. Remplacez le câble HDMI (certifié 18 Gbps minimum pour 4K HDR).\n3. Allumez TV puis Sync Box puis console.\n4. Désactivez temporairement le HDR/DV sur la source pour tester.\n5. Si seul un appareil pose problème, vérifiez les réglages HDCP de la console.', 'Causes fréquentes : Câble HDMI défectueux, ordre de boot TV/box/console, HDCP 2.2 non respecté, ou mode Dolby Vision qui passe en tunnel incompatible.\n\n1. Testez la source → TV sans Sync Box.\n2. Remplacez le câble HDMI (certifié 18 Gbps minimum pour 4K HDR).\n3. Allumez TV puis Sync Box puis console.\n4. Désactivez temporairement le HDR/DV sur la source pour tester.\n5. Si seul un appareil pose problème, vérifiez les réglages HDCP de la console.', 'Causes fréquentes : Câble HDMI défectueux, ordre de boot TV/box/console, HDCP 2.2 non respecté, ou mode Dolby Vision qui passe en tunnel incompatible.\n\n1. Testez la source → TV sans Sync Box.\n2. Remplacez le câble HDMI (certifié 18 Gbps minimum pour 4K HDR).\n3. Allumez TV puis Sync Box puis console.\n4. Désactivez temporairement le HDR/DV sur la source pour tester.\n5. Si seul un appareil pose problème, vérifiez les réglages HDCP de la console.', 'Causes fréquentes : Câble HDMI défectueux, ordre de boot TV/box/console, HDCP 2.2 non respecté, ou mode Dolby Vision qui passe en tunnel incompatible.\n\n1. Testez la source → TV sans Sync Box.\n2. Remplacez le câble HDMI (certifié 18 Gbps minimum pour 4K HDR).\n3. Allumez TV puis Sync Box puis console.\n4. Désactivez temporairement le HDR/DV sur la source pour tester.\n5. Si seul un appareil pose problème, vérifiez les réglages HDCP de la console.', 'Causes fréquentes : Câble HDMI défectueux, ordre de boot TV/box/console, HDCP 2.2 non respecté, ou mode Dolby Vision qui passe en tunnel incompatible.\n\n1. Testez la source → TV sans Sync Box.\n2. Remplacez le câble HDMI (certifié 18 Gbps minimum pour 4K HDR).\n3. Allumez TV puis Sync Box puis console.\n4. Désactivez temporairement le HDR/DV sur la source pour tester.\n5. Si seul un appareil pose problème, vérifiez les réglages HDCP de la console.', 'autre câble HDMI, source de test', 'autre câble HDMI, source de test', 'autre câble HDMI, source de test', 'autre câble HDMI, source de test', 'autre câble HDMI, source de test', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (9, 'hue-sync-box-latence', 5, 1, 3, 'Latence / décalage lumière', 1, '10–20 min', '0 €', 0, 'Hue Sync Box : retard visible entre image et lumières', 'Hue Sync Box : retard visible entre image et lumières', 'Hue Sync Box : retard visible entre image et lumières', 'Hue Sync Box : retard visible entre image et lumières', 'Hue Sync Box : retard visible entre image et lumières', 'Les couleurs arrivent avec 200–500 ms de retard, gênant sur les jeux rapides.', 'Les couleurs arrivent avec 200–500 ms de retard, gênant sur les jeux rapides.', 'Les couleurs arrivent avec 200–500 ms de retard, gênant sur les jeux rapides.', 'Les couleurs arrivent avec 200–500 ms de retard, gênant sur les jeux rapides.', 'Les couleurs arrivent avec 200–500 ms de retard, gênant sur les jeux rapides.', 'Causes fréquentes : Mode synchronisation « fort » avec lissage, TV avec traitement d’image lent (MEMC), ou Bridge surchargé.\n\n1. Dans Hue Sync, baissez l’intensité de sync ou passez en mode « Jeu » / faible latence.\n2. Activez le mode jeu sur la TV (désactivez MEMC).\n3. Limitez le nombre de luminaires dans la zone Entertainment.\n4. Branchez le Bridge en Ethernet filaire.\n5. Latence extrême : testez avec une seule ampoure proche du Bridge.', 'Causes fréquentes : Mode synchronisation « fort » avec lissage, TV avec traitement d’image lent (MEMC), ou Bridge surchargé.\n\n1. Dans Hue Sync, baissez l’intensité de sync ou passez en mode « Jeu » / faible latence.\n2. Activez le mode jeu sur la TV (désactivez MEMC).\n3. Limitez le nombre de luminaires dans la zone Entertainment.\n4. Branchez le Bridge en Ethernet filaire.\n5. Latence extrême : testez avec une seule ampoure proche du Bridge.', 'Causes fréquentes : Mode synchronisation « fort » avec lissage, TV avec traitement d’image lent (MEMC), ou Bridge surchargé.\n\n1. Dans Hue Sync, baissez l’intensité de sync ou passez en mode « Jeu » / faible latence.\n2. Activez le mode jeu sur la TV (désactivez MEMC).\n3. Limitez le nombre de luminaires dans la zone Entertainment.\n4. Branchez le Bridge en Ethernet filaire.\n5. Latence extrême : testez avec une seule ampoure proche du Bridge.', 'Causes fréquentes : Mode synchronisation « fort » avec lissage, TV avec traitement d’image lent (MEMC), ou Bridge surchargé.\n\n1. Dans Hue Sync, baissez l’intensité de sync ou passez en mode « Jeu » / faible latence.\n2. Activez le mode jeu sur la TV (désactivez MEMC).\n3. Limitez le nombre de luminaires dans la zone Entertainment.\n4. Branchez le Bridge en Ethernet filaire.\n5. Latence extrême : testez avec une seule ampoure proche du Bridge.', 'Causes fréquentes : Mode synchronisation « fort » avec lissage, TV avec traitement d’image lent (MEMC), ou Bridge surchargé.\n\n1. Dans Hue Sync, baissez l’intensité de sync ou passez en mode « Jeu » / faible latence.\n2. Activez le mode jeu sur la TV (désactivez MEMC).\n3. Limitez le nombre de luminaires dans la zone Entertainment.\n4. Branchez le Bridge en Ethernet filaire.\n5. Latence extrême : testez avec une seule ampoure proche du Bridge.', 'app Hue Sync (réglages avancés)', 'app Hue Sync (réglages avancés)', 'app Hue Sync (réglages avancés)', 'app Hue Sync (réglages avancés)', 'app Hue Sync (réglages avancés)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (10, 'shelly-dimmer-2-surchauffe', 4, 2, 4, 'Surchauffe / arrêt automatique', 3, '30–60 min', '0–80 €', 0, 'Shelly Dimmer 2 qui chauffe ou s’éteint', 'Shelly Dimmer 2 qui chauffe ou s’éteint', 'Shelly Dimmer 2 qui chauffe ou s’éteint', 'Shelly Dimmer 2 qui chauffe ou s’éteint', 'Shelly Dimmer 2 qui chauffe ou s’éteint', 'Le module devient brûlant, le variateur se coupe, ou l’app Shelly affiche une alerte température.', 'Le module devient brûlant, le variateur se coupe, ou l’app Shelly affiche une alerte température.', 'Le module devient brûlant, le variateur se coupe, ou l’app Shelly affiche une alerte température.', 'Le module devient brûlant, le variateur se coupe, ou l’app Shelly affiche une alerte température.', 'Le module devient brûlant, le variateur se coupe, ou l’app Shelly affiche une alerte température.', 'Causes fréquentes : Surcharge LED (trop de watts), absence de dissipateur dans une boîte étanche, neutre absent mal compensé, ou ampoules non dimmables.\n\n1. Coupez le courant et vérifiez la puissance totale des ampoules (≤ 200 W LED indiqué).\n2. Utilisez uniquement des ampoules dimmables compatibles triac/phase coupée selon réglage Shelly.\n3. Assurez l’espace d’air dans la boîte d’encastrement (ne pas étouffer le module).\n4. Activez la protection thermique dans l’app et baissez le calibrage minimum.\n5. Chaleur anormale à faible charge : SAV Shelly ou électricien.', 'Causes fréquentes : Surcharge LED (trop de watts), absence de dissipateur dans une boîte étanche, neutre absent mal compensé, ou ampoules non dimmables.\n\n1. Coupez le courant et vérifiez la puissance totale des ampoules (≤ 200 W LED indiqué).\n2. Utilisez uniquement des ampoules dimmables compatibles triac/phase coupée selon réglage Shelly.\n3. Assurez l’espace d’air dans la boîte d’encastrement (ne pas étouffer le module).\n4. Activez la protection thermique dans l’app et baissez le calibrage minimum.\n5. Chaleur anormale à faible charge : SAV Shelly ou électricien.', 'Causes fréquentes : Surcharge LED (trop de watts), absence de dissipateur dans une boîte étanche, neutre absent mal compensé, ou ampoules non dimmables.\n\n1. Coupez le courant et vérifiez la puissance totale des ampoules (≤ 200 W LED indiqué).\n2. Utilisez uniquement des ampoules dimmables compatibles triac/phase coupée selon réglage Shelly.\n3. Assurez l’espace d’air dans la boîte d’encastrement (ne pas étouffer le module).\n4. Activez la protection thermique dans l’app et baissez le calibrage minimum.\n5. Chaleur anormale à faible charge : SAV Shelly ou électricien.', 'Causes fréquentes : Surcharge LED (trop de watts), absence de dissipateur dans une boîte étanche, neutre absent mal compensé, ou ampoules non dimmables.\n\n1. Coupez le courant et vérifiez la puissance totale des ampoules (≤ 200 W LED indiqué).\n2. Utilisez uniquement des ampoules dimmables compatibles triac/phase coupée selon réglage Shelly.\n3. Assurez l’espace d’air dans la boîte d’encastrement (ne pas étouffer le module).\n4. Activez la protection thermique dans l’app et baissez le calibrage minimum.\n5. Chaleur anormale à faible charge : SAV Shelly ou électricien.', 'Causes fréquentes : Surcharge LED (trop de watts), absence de dissipateur dans une boîte étanche, neutre absent mal compensé, ou ampoules non dimmables.\n\n1. Coupez le courant et vérifiez la puissance totale des ampoules (≤ 200 W LED indiqué).\n2. Utilisez uniquement des ampoules dimmables compatibles triac/phase coupée selon réglage Shelly.\n3. Assurez l’espace d’air dans la boîte d’encastrement (ne pas étouffer le module).\n4. Activez la protection thermique dans l’app et baissez le calibrage minimum.\n5. Chaleur anormale à faible charge : SAV Shelly ou électricien.', 'tournevis isolé, multimètre', 'tournevis isolé, multimètre', 'tournevis isolé, multimètre', 'tournevis isolé, multimètre', 'tournevis isolé, multimètre', 'Installation sous tension interdite. Coupez le disjoncteur. Charge maximale 200 W LED — ne pas dépasser. Risque d’incendie en cas de surcharge.', 'Installation sous tension interdite. Coupez le disjoncteur. Charge maximale 200 W LED — ne pas dépasser. Risque d’incendie en cas de surcharge.', 'Installation sous tension interdite. Coupez le disjoncteur. Charge maximale 200 W LED — ne pas dépasser. Risque d’incendie en cas de surcharge.', 'Installation sous tension interdite. Coupez le disjoncteur. Charge maximale 200 W LED — ne pas dépasser. Risque d’incendie en cas de surcharge.', 'Installation sous tension interdite. Coupez le disjoncteur. Charge maximale 200 W LED — ne pas dépasser. Risque d’incendie en cas de surcharge.');
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (11, 'shelly-dimmer-2-clignote-min', 4, 2, 4, 'Scintillement à basse luminosité', 2, '15–35 min', '0–20 €', 0, 'Shelly Dimmer 2 : LED qui scintillent au minimum', 'Shelly Dimmer 2 : LED qui scintillent au minimum', 'Shelly Dimmer 2 : LED qui scintillent au minimum', 'Shelly Dimmer 2 : LED qui scintillent au minimum', 'Shelly Dimmer 2 : LED qui scintillent au minimum', 'À 5–15 % de luminosité, les ampoules flicker ou s’éteignent ; à 100 % tout va bien.', 'À 5–15 % de luminosité, les ampoules flicker ou s’éteignent ; à 100 % tout va bien.', 'À 5–15 % de luminosité, les ampoules flicker ou s’éteignent ; à 100 % tout va bien.', 'À 5–15 % de luminosité, les ampoules flicker ou s’éteignent ; à 100 % tout va bien.', 'À 5–15 % de luminosité, les ampoules flicker ou s’éteignent ; à 100 % tout va bien.', 'Causes fréquentes : Calibrage min/max incorrect, type d’ampoule (trailing edge vs leading edge), charge trop faible sur une seule ampoule.\n\n1. Lancez l’auto-calibrage dans l’app Shelly (Dimmer settings → Calibrate).\n2. Basculez leading/trailing edge selon la notice ampoule.\n3. Augmentez la charge minimale en ajoutant une ampoule ou un « dimmer bypass » Shelly si une seule LED.\n4. Montez le seuil minimum logiciel (min brightness).\n5. Si incompatible : remplacez les ampoules par des modèles certifiés dimmables.', 'Causes fréquentes : Calibrage min/max incorrect, type d’ampoule (trailing edge vs leading edge), charge trop faible sur une seule ampoule.\n\n1. Lancez l’auto-calibrage dans l’app Shelly (Dimmer settings → Calibrate).\n2. Basculez leading/trailing edge selon la notice ampoule.\n3. Augmentez la charge minimale en ajoutant une ampoule ou un « dimmer bypass » Shelly si une seule LED.\n4. Montez le seuil minimum logiciel (min brightness).\n5. Si incompatible : remplacez les ampoules par des modèles certifiés dimmables.', 'Causes fréquentes : Calibrage min/max incorrect, type d’ampoule (trailing edge vs leading edge), charge trop faible sur une seule ampoule.\n\n1. Lancez l’auto-calibrage dans l’app Shelly (Dimmer settings → Calibrate).\n2. Basculez leading/trailing edge selon la notice ampoule.\n3. Augmentez la charge minimale en ajoutant une ampoule ou un « dimmer bypass » Shelly si une seule LED.\n4. Montez le seuil minimum logiciel (min brightness).\n5. Si incompatible : remplacez les ampoules par des modèles certifiés dimmables.', 'Causes fréquentes : Calibrage min/max incorrect, type d’ampoule (trailing edge vs leading edge), charge trop faible sur une seule ampoule.\n\n1. Lancez l’auto-calibrage dans l’app Shelly (Dimmer settings → Calibrate).\n2. Basculez leading/trailing edge selon la notice ampoule.\n3. Augmentez la charge minimale en ajoutant une ampoule ou un « dimmer bypass » Shelly si une seule LED.\n4. Montez le seuil minimum logiciel (min brightness).\n5. Si incompatible : remplacez les ampoules par des modèles certifiés dimmables.', 'Causes fréquentes : Calibrage min/max incorrect, type d’ampoule (trailing edge vs leading edge), charge trop faible sur une seule ampoule.\n\n1. Lancez l’auto-calibrage dans l’app Shelly (Dimmer settings → Calibrate).\n2. Basculez leading/trailing edge selon la notice ampoule.\n3. Augmentez la charge minimale en ajoutant une ampoule ou un « dimmer bypass » Shelly si une seule LED.\n4. Montez le seuil minimum logiciel (min brightness).\n5. Si incompatible : remplacez les ampoules par des modèles certifiés dimmables.', 'app Shelly, ampoules dimmables', 'app Shelly, ampoules dimmables', 'app Shelly, ampoules dimmables', 'app Shelly, ampoules dimmables', 'app Shelly, ampoules dimmables', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (12, 'shelly-dimmer-2-wifi-offline', 4, 2, 4, 'Wi-Fi offline / cloud déconnecté', 2, '15–30 min', '0 €', 0, 'Shelly Dimmer 2 hors ligne dans l’app', 'Shelly Dimmer 2 hors ligne dans l’app', 'Shelly Dimmer 2 hors ligne dans l’app', 'Shelly Dimmer 2 hors ligne dans l’app', 'Shelly Dimmer 2 hors ligne dans l’app', 'Le module ne répond plus aux commandes cloud ; parfois le variateur physique fonctionne encore.', 'Le module ne répond plus aux commandes cloud ; parfois le variateur physique fonctionne encore.', 'Le module ne répond plus aux commandes cloud ; parfois le variateur physique fonctionne encore.', 'Le module ne répond plus aux commandes cloud ; parfois le variateur physique fonctionne encore.', 'Le module ne répond plus aux commandes cloud ; parfois le variateur physique fonctionne encore.', 'Causes fréquentes : Changement de mot de passe Wi-Fi, réseau 5 GHz seul, IP DHCP renouvelée, ou serveur Shelly en maintenance.\n\n1. Vérifiez que le Wi-Fi 2,4 GHz est actif.\n2. Accédez en local via l’IP du module (si connu) ou AP mode Shelly.\n3. Reconfigurez le Wi-Fi depuis l’app.\n4. Réservez une IP DHCP pour le Shelly dans le routeur.\n5. Activez le contrôle local MQTT/Home Assistant si le cloud est instable.', 'Causes fréquentes : Changement de mot de passe Wi-Fi, réseau 5 GHz seul, IP DHCP renouvelée, ou serveur Shelly en maintenance.\n\n1. Vérifiez que le Wi-Fi 2,4 GHz est actif.\n2. Accédez en local via l’IP du module (si connu) ou AP mode Shelly.\n3. Reconfigurez le Wi-Fi depuis l’app.\n4. Réservez une IP DHCP pour le Shelly dans le routeur.\n5. Activez le contrôle local MQTT/Home Assistant si le cloud est instable.', 'Causes fréquentes : Changement de mot de passe Wi-Fi, réseau 5 GHz seul, IP DHCP renouvelée, ou serveur Shelly en maintenance.\n\n1. Vérifiez que le Wi-Fi 2,4 GHz est actif.\n2. Accédez en local via l’IP du module (si connu) ou AP mode Shelly.\n3. Reconfigurez le Wi-Fi depuis l’app.\n4. Réservez une IP DHCP pour le Shelly dans le routeur.\n5. Activez le contrôle local MQTT/Home Assistant si le cloud est instable.', 'Causes fréquentes : Changement de mot de passe Wi-Fi, réseau 5 GHz seul, IP DHCP renouvelée, ou serveur Shelly en maintenance.\n\n1. Vérifiez que le Wi-Fi 2,4 GHz est actif.\n2. Accédez en local via l’IP du module (si connu) ou AP mode Shelly.\n3. Reconfigurez le Wi-Fi depuis l’app.\n4. Réservez une IP DHCP pour le Shelly dans le routeur.\n5. Activez le contrôle local MQTT/Home Assistant si le cloud est instable.', 'Causes fréquentes : Changement de mot de passe Wi-Fi, réseau 5 GHz seul, IP DHCP renouvelée, ou serveur Shelly en maintenance.\n\n1. Vérifiez que le Wi-Fi 2,4 GHz est actif.\n2. Accédez en local via l’IP du module (si connu) ou AP mode Shelly.\n3. Reconfigurez le Wi-Fi depuis l’app.\n4. Réservez une IP DHCP pour le Shelly dans le routeur.\n5. Activez le contrôle local MQTT/Home Assistant si le cloud est instable.', 'routeur 2,4 GHz, app Shelly', 'routeur 2,4 GHz, app Shelly', 'routeur 2,4 GHz, app Shelly', 'routeur 2,4 GHz, app Shelly', 'routeur 2,4 GHz, app Shelly', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (13, 'shelly-dimmer-2-neutre-absent', 4, 2, 4, 'Neutre absent / module ne s’allume pas', 4, '45–90 min', '15–120 €', 0, 'Shelly Dimmer 2 sans fil neutre au plafonnier', 'Shelly Dimmer 2 sans fil neutre au plafonnier', 'Shelly Dimmer 2 sans fil neutre au plafonnier', 'Shelly Dimmer 2 sans fil neutre au plafonnier', 'Shelly Dimmer 2 sans fil neutre au plafonnier', 'Le module ne démarre pas, LED Wi-Fi éteinte, ou l’ampoule reste faiblement allumée après extinction.', 'Le module ne démarre pas, LED Wi-Fi éteinte, ou l’ampoule reste faiblement allumée après extinction.', 'Le module ne démarre pas, LED Wi-Fi éteinte, ou l’ampoule reste faiblement allumée après extinction.', 'Le module ne démarre pas, LED Wi-Fi éteinte, ou l’ampoule reste faiblement allumée après extinction.', 'Le module ne démarre pas, LED Wi-Fi éteinte, ou l’ampoule reste faiblement allumée après extinction.', 'Causes fréquentes : Installation sans neutre sans Shelly Bypass, charge capacitive des LED, ou fil de retour lampe mal identifié.\n\n1. Confirmez la présence du neutre (bleu) dans la boîte — sinon utilisez le Shelly Bypass en série avec l’ampoule.\n2. Suivez strictement le schéma Shelly pour neutre absent.\n3. Ne combinez pas avec des ampoules non dimmables.\n4. Faites tirer un neutre par un électricien si la configuration est complexe (va-et-vient).\n5. En cas de doute sur les fils, arrêtez et faites appel à un pro.', 'Causes fréquentes : Installation sans neutre sans Shelly Bypass, charge capacitive des LED, ou fil de retour lampe mal identifié.\n\n1. Confirmez la présence du neutre (bleu) dans la boîte — sinon utilisez le Shelly Bypass en série avec l’ampoule.\n2. Suivez strictement le schéma Shelly pour neutre absent.\n3. Ne combinez pas avec des ampoules non dimmables.\n4. Faites tirer un neutre par un électricien si la configuration est complexe (va-et-vient).\n5. En cas de doute sur les fils, arrêtez et faites appel à un pro.', 'Causes fréquentes : Installation sans neutre sans Shelly Bypass, charge capacitive des LED, ou fil de retour lampe mal identifié.\n\n1. Confirmez la présence du neutre (bleu) dans la boîte — sinon utilisez le Shelly Bypass en série avec l’ampoule.\n2. Suivez strictement le schéma Shelly pour neutre absent.\n3. Ne combinez pas avec des ampoules non dimmables.\n4. Faites tirer un neutre par un électricien si la configuration est complexe (va-et-vient).\n5. En cas de doute sur les fils, arrêtez et faites appel à un pro.', 'Causes fréquentes : Installation sans neutre sans Shelly Bypass, charge capacitive des LED, ou fil de retour lampe mal identifié.\n\n1. Confirmez la présence du neutre (bleu) dans la boîte — sinon utilisez le Shelly Bypass en série avec l’ampoule.\n2. Suivez strictement le schéma Shelly pour neutre absent.\n3. Ne combinez pas avec des ampoules non dimmables.\n4. Faites tirer un neutre par un électricien si la configuration est complexe (va-et-vient).\n5. En cas de doute sur les fils, arrêtez et faites appel à un pro.', 'Causes fréquentes : Installation sans neutre sans Shelly Bypass, charge capacitive des LED, ou fil de retour lampe mal identifié.\n\n1. Confirmez la présence du neutre (bleu) dans la boîte — sinon utilisez le Shelly Bypass en série avec l’ampoule.\n2. Suivez strictement le schéma Shelly pour neutre absent.\n3. Ne combinez pas avec des ampoules non dimmables.\n4. Faites tirer un neutre par un électricien si la configuration est complexe (va-et-vient).\n5. En cas de doute sur les fils, arrêtez et faites appel à un pro.', 'Shelly Bypass, électricien si tirage neutre', 'Shelly Bypass, électricien si tirage neutre', 'Shelly Bypass, électricien si tirage neutre', 'Shelly Bypass, électricien si tirage neutre', 'Shelly Bypass, électricien si tirage neutre', 'Travail au plafonnier 230 V. Sans neutre au point lumineux, le bypass doit être posé selon le schéma officiel Shelly — erreur = choc ou incendie.', 'Travail au plafonnier 230 V. Sans neutre au point lumineux, le bypass doit être posé selon le schéma officiel Shelly — erreur = choc ou incendie.', 'Travail au plafonnier 230 V. Sans neutre au point lumineux, le bypass doit être posé selon le schéma officiel Shelly — erreur = choc ou incendie.', 'Travail au plafonnier 230 V. Sans neutre au point lumineux, le bypass doit être posé selon le schéma officiel Shelly — erreur = choc ou incendie.', 'Travail au plafonnier 230 V. Sans neutre au point lumineux, le bypass doit être posé selon le schéma officiel Shelly — erreur = choc ou incendie.');
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (14, 'shelly-plus-1pm-surcharge', 4, 2, 5, 'Surcharge / relais qui lâche', 3, '20–40 min', '0–50 €', 0, 'Shelly Plus 1PM : disjonction ou ampoules qui clignotent', 'Shelly Plus 1PM : disjonction ou ampoules qui clignotent', 'Shelly Plus 1PM : disjonction ou ampoules qui clignotent', 'Shelly Plus 1PM : disjonction ou ampoules qui clignotent', 'Shelly Plus 1PM : disjonction ou ampoules qui clignotent', 'Le relais coupe en boucle, la mesure de puissance affiche des pics, ou odeur de composant chaud.', 'Le relais coupe en boucle, la mesure de puissance affiche des pics, ou odeur de composant chaud.', 'Le relais coupe en boucle, la mesure de puissance affiche des pics, ou odeur de composant chaud.', 'Le relais coupe en boucle, la mesure de puissance affiche des pics, ou odeur de composant chaud.', 'Le relais coupe en boucle, la mesure de puissance affiche des pics, ou odeur de composant chaud.', 'Causes fréquentes : Charge inductive (transformateur halogène ancien), court-circuit partiel, ou luminaire LED avec driver défaillant.\n\n1. Coupez le courant et inspectez le luminaire (driver LED).\n2. Vérifiez la puissance max sur l’app (alertes).\n3. Retirez les anciens transformateurs 12 V si vous avez migré en LED native 230 V.\n4. Remplacez le luminaire suspect.\n5. Défaut matériel du Shelly : garantie Shelly.', 'Causes fréquentes : Charge inductive (transformateur halogène ancien), court-circuit partiel, ou luminaire LED avec driver défaillant.\n\n1. Coupez le courant et inspectez le luminaire (driver LED).\n2. Vérifiez la puissance max sur l’app (alertes).\n3. Retirez les anciens transformateurs 12 V si vous avez migré en LED native 230 V.\n4. Remplacez le luminaire suspect.\n5. Défaut matériel du Shelly : garantie Shelly.', 'Causes fréquentes : Charge inductive (transformateur halogène ancien), court-circuit partiel, ou luminaire LED avec driver défaillant.\n\n1. Coupez le courant et inspectez le luminaire (driver LED).\n2. Vérifiez la puissance max sur l’app (alertes).\n3. Retirez les anciens transformateurs 12 V si vous avez migré en LED native 230 V.\n4. Remplacez le luminaire suspect.\n5. Défaut matériel du Shelly : garantie Shelly.', 'Causes fréquentes : Charge inductive (transformateur halogène ancien), court-circuit partiel, ou luminaire LED avec driver défaillant.\n\n1. Coupez le courant et inspectez le luminaire (driver LED).\n2. Vérifiez la puissance max sur l’app (alertes).\n3. Retirez les anciens transformateurs 12 V si vous avez migré en LED native 230 V.\n4. Remplacez le luminaire suspect.\n5. Défaut matériel du Shelly : garantie Shelly.', 'Causes fréquentes : Charge inductive (transformateur halogène ancien), court-circuit partiel, ou luminaire LED avec driver défaillant.\n\n1. Coupez le courant et inspectez le luminaire (driver LED).\n2. Vérifiez la puissance max sur l’app (alertes).\n3. Retirez les anciens transformateurs 12 V si vous avez migré en LED native 230 V.\n4. Remplacez le luminaire suspect.\n5. Défaut matériel du Shelly : garantie Shelly.', 'app Shelly (mesure puissance)', 'app Shelly (mesure puissance)', 'app Shelly (mesure puissance)', 'app Shelly (mesure puissance)', 'app Shelly (mesure puissance)', 'Ne pas dépasser 16 A / charge indiquée. Coupez le disjoncteur avant intervention.', 'Ne pas dépasser 16 A / charge indiquée. Coupez le disjoncteur avant intervention.', 'Ne pas dépasser 16 A / charge indiquée. Coupez le disjoncteur avant intervention.', 'Ne pas dépasser 16 A / charge indiquée. Coupez le disjoncteur avant intervention.', 'Ne pas dépasser 16 A / charge indiquée. Coupez le disjoncteur avant intervention.');
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (15, 'shelly-plus-1pm-mesure-zero', 4, 2, 5, 'Mesure conso à 0 W incorrecte', 2, '10–25 min', '0 €', 0, 'Shelly Plus 1PM affiche 0 W alors que la lampe est allumée', 'Shelly Plus 1PM affiche 0 W alors que la lampe est allumée', 'Shelly Plus 1PM affiche 0 W alors que la lampe est allumée', 'Shelly Plus 1PM affiche 0 W alors que la lampe est allumée', 'Shelly Plus 1PM affiche 0 W alors que la lampe est allumée', 'La télémesure reste à 0 ou très sous-estimée ; les automatisations basées sur la puissance ne se déclenchent pas.', 'La télémesure reste à 0 ou très sous-estimée ; les automatisations basées sur la puissance ne se déclenchent pas.', 'La télémesure reste à 0 ou très sous-estimée ; les automatisations basées sur la puissance ne se déclenchent pas.', 'La télémesure reste à 0 ou très sous-estimée ; les automatisations basées sur la puissance ne se déclenchent pas.', 'La télémesure reste à 0 ou très sous-estimée ; les automatisations basées sur la puissance ne se déclenchent pas.', 'Causes fréquentes : Calibration énergétique non faite, LED à très faible consommation sous le seuil, ou câblage phase/neutre inversé sur la mesure.\n\n1. Vérifiez le câblage selon le manuel (entrée/sortie phase pour la mesure).\n2. Calibrez avec une charge résistive connue (60 W halogène) pour tester.\n3. Les LED < 5 W peuvent être sous le seuil — normal sur certains firmware.\n4. Mettez à jour le firmware Shelly.\n5. Besoin de mesure précise LED : utilisez un wattmètre externe pour référence.', 'Causes fréquentes : Calibration énergétique non faite, LED à très faible consommation sous le seuil, ou câblage phase/neutre inversé sur la mesure.\n\n1. Vérifiez le câblage selon le manuel (entrée/sortie phase pour la mesure).\n2. Calibrez avec une charge résistive connue (60 W halogène) pour tester.\n3. Les LED < 5 W peuvent être sous le seuil — normal sur certains firmware.\n4. Mettez à jour le firmware Shelly.\n5. Besoin de mesure précise LED : utilisez un wattmètre externe pour référence.', 'Causes fréquentes : Calibration énergétique non faite, LED à très faible consommation sous le seuil, ou câblage phase/neutre inversé sur la mesure.\n\n1. Vérifiez le câblage selon le manuel (entrée/sortie phase pour la mesure).\n2. Calibrez avec une charge résistive connue (60 W halogène) pour tester.\n3. Les LED < 5 W peuvent être sous le seuil — normal sur certains firmware.\n4. Mettez à jour le firmware Shelly.\n5. Besoin de mesure précise LED : utilisez un wattmètre externe pour référence.', 'Causes fréquentes : Calibration énergétique non faite, LED à très faible consommation sous le seuil, ou câblage phase/neutre inversé sur la mesure.\n\n1. Vérifiez le câblage selon le manuel (entrée/sortie phase pour la mesure).\n2. Calibrez avec une charge résistive connue (60 W halogène) pour tester.\n3. Les LED < 5 W peuvent être sous le seuil — normal sur certains firmware.\n4. Mettez à jour le firmware Shelly.\n5. Besoin de mesure précise LED : utilisez un wattmètre externe pour référence.', 'Causes fréquentes : Calibration énergétique non faite, LED à très faible consommation sous le seuil, ou câblage phase/neutre inversé sur la mesure.\n\n1. Vérifiez le câblage selon le manuel (entrée/sortie phase pour la mesure).\n2. Calibrez avec une charge résistive connue (60 W halogène) pour tester.\n3. Les LED < 5 W peuvent être sous le seuil — normal sur certains firmware.\n4. Mettez à jour le firmware Shelly.\n5. Besoin de mesure précise LED : utilisez un wattmètre externe pour référence.', 'app Shelly, charge connue (lampe à incandescence test)', 'app Shelly, charge connue (lampe à incandescence test)', 'app Shelly, charge connue (lampe à incandescence test)', 'app Shelly, charge connue (lampe à incandescence test)', 'app Shelly, charge connue (lampe à incandescence test)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (16, 'shelly-plus-1pm-ghosting', 4, 2, 5, 'Lueur fantôme / lampe faiblement allumée', 2, '15–30 min', '4–15 €', 0, 'Shelly Plus 1PM : ampoule LED reste légèrement allumée', 'Shelly Plus 1PM : ampoule LED reste légèrement allumée', 'Shelly Plus 1PM : ampoule LED reste légèrement allumée', 'Shelly Plus 1PM : ampoule LED reste légèrement allumée', 'Shelly Plus 1PM : ampoule LED reste légèrement allumée', 'Après extinction via l’app, une faible lueur persiste sur les LED (ghosting).', 'Après extinction via l’app, une faible lueur persiste sur les LED (ghosting).', 'Après extinction via l’app, une faible lueur persiste sur les LED (ghosting).', 'Après extinction via l’app, une faible lueur persiste sur les LED (ghosting).', 'Après extinction via l’app, une faible lueur persiste sur les LED (ghosting).', 'Causes fréquentes : Courant de fuite du relais, LED très sensibles, ou neutre commun avec autre circuit.\n\n1. Activez l’option « Turn off after » ou zero-cross si disponible.\n2. Ajoutez un condensateur de suppression adapté aux LED (voir fiche Legrand/Shelly).\n3. Remplacez par des ampoules moins sensibles au courant résiduel.\n4. Évitez les circuits partagés avec minuteries électroniques.\n5. Ghosting fort : vérifiez le câblage neutre avec un électricien.', 'Causes fréquentes : Courant de fuite du relais, LED très sensibles, ou neutre commun avec autre circuit.\n\n1. Activez l’option « Turn off after » ou zero-cross si disponible.\n2. Ajoutez un condensateur de suppression adapté aux LED (voir fiche Legrand/Shelly).\n3. Remplacez par des ampoules moins sensibles au courant résiduel.\n4. Évitez les circuits partagés avec minuteries électroniques.\n5. Ghosting fort : vérifiez le câblage neutre avec un électricien.', 'Causes fréquentes : Courant de fuite du relais, LED très sensibles, ou neutre commun avec autre circuit.\n\n1. Activez l’option « Turn off after » ou zero-cross si disponible.\n2. Ajoutez un condensateur de suppression adapté aux LED (voir fiche Legrand/Shelly).\n3. Remplacez par des ampoules moins sensibles au courant résiduel.\n4. Évitez les circuits partagés avec minuteries électroniques.\n5. Ghosting fort : vérifiez le câblage neutre avec un électricien.', 'Causes fréquentes : Courant de fuite du relais, LED très sensibles, ou neutre commun avec autre circuit.\n\n1. Activez l’option « Turn off after » ou zero-cross si disponible.\n2. Ajoutez un condensateur de suppression adapté aux LED (voir fiche Legrand/Shelly).\n3. Remplacez par des ampoules moins sensibles au courant résiduel.\n4. Évitez les circuits partagés avec minuteries électroniques.\n5. Ghosting fort : vérifiez le câblage neutre avec un électricien.', 'Causes fréquentes : Courant de fuite du relais, LED très sensibles, ou neutre commun avec autre circuit.\n\n1. Activez l’option « Turn off after » ou zero-cross si disponible.\n2. Ajoutez un condensateur de suppression adapté aux LED (voir fiche Legrand/Shelly).\n3. Remplacez par des ampoules moins sensibles au courant résiduel.\n4. Évitez les circuits partagés avec minuteries électroniques.\n5. Ghosting fort : vérifiez le câblage neutre avec un électricien.', 'condensateur anti-fantôme ou ampoules compatibles', 'condensateur anti-fantôme ou ampoules compatibles', 'condensateur anti-fantôme ou ampoules compatibles', 'condensateur anti-fantôme ou ampoules compatibles', 'condensateur anti-fantôme ou ampoules compatibles', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (17, 'ikea-tradfri-pairing-echoue', 1, 3, 6, 'Appairage échoué / ampoule introuvable', 2, '15–35 min', '0 €', 0, 'Passerelle TRÅDFRI : échec d’appairage ampoule', 'Passerelle TRÅDFRI : échec d’appairage ampoule', 'Passerelle TRÅDFRI : échec d’appairage ampoule', 'Passerelle TRÅDFRI : échec d’appairage ampoule', 'Passerelle TRÅDFRI : échec d’appairage ampoule', 'L’app reste sur « recherche » ou échoue à 90 % ; l’ampoule clignote mais n’apparaît pas.', 'L’app reste sur « recherche » ou échoue à 90 % ; l’ampoule clignote mais n’apparaît pas.', 'L’app reste sur « recherche » ou échoue à 90 % ; l’ampoule clignote mais n’apparaît pas.', 'L’app reste sur « recherche » ou échoue à 90 % ; l’ampoule clignote mais n’apparaît pas.', 'L’app reste sur « recherche » ou échoue à 90 % ; l’ampoule clignote mais n’apparaît pas.', 'Causes fréquentes : Passerelle pas à jour, ampoule déjà liée à un autre hub, distance Zigbee excessive, ou réseau Wi-Fi invité.\n\n1. Mettez à jour la passerelle via l’app (firmware).\n2. Réinitialisez l’ampoule (6 cycles on/off rapides selon modèle TRÅDFRI).\n3. Placez l’ampoule à côté de la passerelle pour l’appairage.\n4. Utilisez le même réseau Wi-Fi que le téléphone (pas invité).\n5. Ampoule achetée d’occasion : reset obligatoire.', 'Causes fréquentes : Passerelle pas à jour, ampoule déjà liée à un autre hub, distance Zigbee excessive, ou réseau Wi-Fi invité.\n\n1. Mettez à jour la passerelle via l’app (firmware).\n2. Réinitialisez l’ampoule (6 cycles on/off rapides selon modèle TRÅDFRI).\n3. Placez l’ampoule à côté de la passerelle pour l’appairage.\n4. Utilisez le même réseau Wi-Fi que le téléphone (pas invité).\n5. Ampoule achetée d’occasion : reset obligatoire.', 'Causes fréquentes : Passerelle pas à jour, ampoule déjà liée à un autre hub, distance Zigbee excessive, ou réseau Wi-Fi invité.\n\n1. Mettez à jour la passerelle via l’app (firmware).\n2. Réinitialisez l’ampoule (6 cycles on/off rapides selon modèle TRÅDFRI).\n3. Placez l’ampoule à côté de la passerelle pour l’appairage.\n4. Utilisez le même réseau Wi-Fi que le téléphone (pas invité).\n5. Ampoule achetée d’occasion : reset obligatoire.', 'Causes fréquentes : Passerelle pas à jour, ampoule déjà liée à un autre hub, distance Zigbee excessive, ou réseau Wi-Fi invité.\n\n1. Mettez à jour la passerelle via l’app (firmware).\n2. Réinitialisez l’ampoule (6 cycles on/off rapides selon modèle TRÅDFRI).\n3. Placez l’ampoule à côté de la passerelle pour l’appairage.\n4. Utilisez le même réseau Wi-Fi que le téléphone (pas invité).\n5. Ampoule achetée d’occasion : reset obligatoire.', 'Causes fréquentes : Passerelle pas à jour, ampoule déjà liée à un autre hub, distance Zigbee excessive, ou réseau Wi-Fi invité.\n\n1. Mettez à jour la passerelle via l’app (firmware).\n2. Réinitialisez l’ampoule (6 cycles on/off rapides selon modèle TRÅDFRI).\n3. Placez l’ampoule à côté de la passerelle pour l’appairage.\n4. Utilisez le même réseau Wi-Fi que le téléphone (pas invité).\n5. Ampoule achetée d’occasion : reset obligatoire.', 'app IKEA Home smart, ampoule TRÅDFRI à 10 cm', 'app IKEA Home smart, ampoule TRÅDFRI à 10 cm', 'app IKEA Home smart, ampoule TRÅDFRI à 10 cm', 'app IKEA Home smart, ampoule TRÅDFRI à 10 cm', 'app IKEA Home smart, ampoule TRÅDFRI à 10 cm', NULL, NULL, NULL, NULL, NULL);
