INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (26, 'govee-bulb-pairing-bluetooth', 2, 4, 9, 'Échec pairing Bluetooth / Wi-Fi', 2, '10–20 min', '0 €', 0, 'Ampoule Govee : ne s’ajoute pas à l’app', 'Ampoule Govee : ne s’ajoute pas à l’app', 'Ampoule Govee : ne s’ajoute pas à l’app', 'Ampoule Govee : ne s’ajoute pas à l’app', 'Ampoule Govee : ne s’ajoute pas à l’app', 'L’app ne trouve pas l’ampoule ou la connexion échoue à la fin.', 'L’app ne trouve pas l’ampoule ou la connexion échoue à la fin.', 'L’app ne trouve pas l’ampoule ou la connexion échoue à la fin.', 'L’app ne trouve pas l’ampoule ou la connexion échoue à la fin.', 'L’app ne trouve pas l’ampoule ou la connexion échoue à la fin.', 'Causes fréquentes : Permissions Bluetooth/localisation refusées, ampoule trop loin, ou déjà liée à un autre compte Govee.\n\n1. Accordez Bluetooth + localisation à Govee Home.\n2. Éteignez autres téléphones Govee à proximité.\n3. Reset ampoule (3 on/off rapides selon modèle H600x).\n4. Configurez d’abord en Bluetooth proche, puis Wi-Fi.\n5. Compte cloud : déconnectez l’ampoule de l’ancien compte.', 'Causes fréquentes : Permissions Bluetooth/localisation refusées, ampoule trop loin, ou déjà liée à un autre compte Govee.\n\n1. Accordez Bluetooth + localisation à Govee Home.\n2. Éteignez autres téléphones Govee à proximité.\n3. Reset ampoule (3 on/off rapides selon modèle H600x).\n4. Configurez d’abord en Bluetooth proche, puis Wi-Fi.\n5. Compte cloud : déconnectez l’ampoule de l’ancien compte.', 'Causes fréquentes : Permissions Bluetooth/localisation refusées, ampoule trop loin, ou déjà liée à un autre compte Govee.\n\n1. Accordez Bluetooth + localisation à Govee Home.\n2. Éteignez autres téléphones Govee à proximité.\n3. Reset ampoule (3 on/off rapides selon modèle H600x).\n4. Configurez d’abord en Bluetooth proche, puis Wi-Fi.\n5. Compte cloud : déconnectez l’ampoule de l’ancien compte.', 'Causes fréquentes : Permissions Bluetooth/localisation refusées, ampoule trop loin, ou déjà liée à un autre compte Govee.\n\n1. Accordez Bluetooth + localisation à Govee Home.\n2. Éteignez autres téléphones Govee à proximité.\n3. Reset ampoule (3 on/off rapides selon modèle H600x).\n4. Configurez d’abord en Bluetooth proche, puis Wi-Fi.\n5. Compte cloud : déconnectez l’ampoule de l’ancien compte.', 'Causes fréquentes : Permissions Bluetooth/localisation refusées, ampoule trop loin, ou déjà liée à un autre compte Govee.\n\n1. Accordez Bluetooth + localisation à Govee Home.\n2. Éteignez autres téléphones Govee à proximité.\n3. Reset ampoule (3 on/off rapides selon modèle H600x).\n4. Configurez d’abord en Bluetooth proche, puis Wi-Fi.\n5. Compte cloud : déconnectez l’ampoule de l’ancien compte.', 'Bluetooth activé, localisation (Android)', 'Bluetooth activé, localisation (Android)', 'Bluetooth activé, localisation (Android)', 'Bluetooth activé, localisation (Android)', 'Bluetooth activé, localisation (Android)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (27, 'govee-bulb-music-sync-lag', 2, 4, 9, 'Music sync décalé / ne réagit pas', 1, '5–15 min', '0 €', 0, 'Ampoule Govee : mode musique peu réactif', 'Ampoule Govee : mode musique peu réactif', 'Ampoule Govee : mode musique peu réactif', 'Ampoule Govee : mode musique peu réactif', 'Ampoule Govee : mode musique peu réactif', 'Les couleurs réagissent mal au son ou avec retard important.', 'Les couleurs réagissent mal au son ou avec retard important.', 'Les couleurs réagissent mal au son ou avec retard important.', 'Les couleurs réagissent mal au son ou avec retard important.', 'Les couleurs réagissent mal au son ou avec retard important.', 'Causes fréquentes : Micro du téléphone utilisé au lieu du micro de l’ampoule (si présent), volume trop bas, ou latence Bluetooth.\n\n1. Activez le mode musique adapté (via ampoule ou téléphone selon modèle).\n2. Augmentez le volume source sans saturation.\n3. Rapprochez le téléphone si le micro est celui du mobile.\n4. Passez en Wi-Fi plutôt que Bluetooth seul.\n5. Désactivez les économiseurs de batterie sur l’app.', 'Causes fréquentes : Micro du téléphone utilisé au lieu du micro de l’ampoule (si présent), volume trop bas, ou latence Bluetooth.\n\n1. Activez le mode musique adapté (via ampoule ou téléphone selon modèle).\n2. Augmentez le volume source sans saturation.\n3. Rapprochez le téléphone si le micro est celui du mobile.\n4. Passez en Wi-Fi plutôt que Bluetooth seul.\n5. Désactivez les économiseurs de batterie sur l’app.', 'Causes fréquentes : Micro du téléphone utilisé au lieu du micro de l’ampoule (si présent), volume trop bas, ou latence Bluetooth.\n\n1. Activez le mode musique adapté (via ampoule ou téléphone selon modèle).\n2. Augmentez le volume source sans saturation.\n3. Rapprochez le téléphone si le micro est celui du mobile.\n4. Passez en Wi-Fi plutôt que Bluetooth seul.\n5. Désactivez les économiseurs de batterie sur l’app.', 'Causes fréquentes : Micro du téléphone utilisé au lieu du micro de l’ampoule (si présent), volume trop bas, ou latence Bluetooth.\n\n1. Activez le mode musique adapté (via ampoule ou téléphone selon modèle).\n2. Augmentez le volume source sans saturation.\n3. Rapprochez le téléphone si le micro est celui du mobile.\n4. Passez en Wi-Fi plutôt que Bluetooth seul.\n5. Désactivez les économiseurs de batterie sur l’app.', 'Causes fréquentes : Micro du téléphone utilisé au lieu du micro de l’ampoule (si présent), volume trop bas, ou latence Bluetooth.\n\n1. Activez le mode musique adapté (via ampoule ou téléphone selon modèle).\n2. Augmentez le volume source sans saturation.\n3. Rapprochez le téléphone si le micro est celui du mobile.\n4. Passez en Wi-Fi plutôt que Bluetooth seul.\n5. Désactivez les économiseurs de batterie sur l’app.', 'micro du téléphone, mode musique Govee', 'micro du téléphone, mode musique Govee', 'micro du téléphone, mode musique Govee', 'micro du téléphone, mode musique Govee', 'micro du téléphone, mode musique Govee', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (28, 'govee-bulb-firmware-brick', 2, 4, 9, 'Bloquée après mise à jour OTA', 3, '20–40 min', '0–15 €', 1, 'Ampoule Govee bloquée après mise à jour firmware', 'Ampoule Govee bloquée après mise à jour firmware', 'Ampoule Govee bloquée après mise à jour firmware', 'Ampoule Govee bloquée après mise à jour firmware', 'Ampoule Govee bloquée après mise à jour firmware', 'L’ampoule ne répond plus, reste d’une couleur fixe, ou disparaît de l’app après OTA.', 'L’ampoule ne répond plus, reste d’une couleur fixe, ou disparaît de l’app après OTA.', 'L’ampoule ne répond plus, reste d’une couleur fixe, ou disparaît de l’app après OTA.', 'L’ampoule ne répond plus, reste d’une couleur fixe, ou disparaît de l’app après OTA.', 'L’ampoule ne répond plus, reste d’une couleur fixe, ou disparaît de l’app après OTA.', 'Causes fréquentes : Coupure réseau pendant OTA, bug firmware rare, ou flash corrompu.\n\n1. Coupez l’alimentation 10 s, rallumez.\n2. Laissez l’ampoule près du routeur et relancez la mise à jour.\n3. Essayez l’ajout manuel en mode pairing.\n4. Contactez le support Govee avec le modèle exact (H600x).\n5. Sous garantie : remplacement.', 'Causes fréquentes : Coupure réseau pendant OTA, bug firmware rare, ou flash corrompu.\n\n1. Coupez l’alimentation 10 s, rallumez.\n2. Laissez l’ampoule près du routeur et relancez la mise à jour.\n3. Essayez l’ajout manuel en mode pairing.\n4. Contactez le support Govee avec le modèle exact (H600x).\n5. Sous garantie : remplacement.', 'Causes fréquentes : Coupure réseau pendant OTA, bug firmware rare, ou flash corrompu.\n\n1. Coupez l’alimentation 10 s, rallumez.\n2. Laissez l’ampoule près du routeur et relancez la mise à jour.\n3. Essayez l’ajout manuel en mode pairing.\n4. Contactez le support Govee avec le modèle exact (H600x).\n5. Sous garantie : remplacement.', 'Causes fréquentes : Coupure réseau pendant OTA, bug firmware rare, ou flash corrompu.\n\n1. Coupez l’alimentation 10 s, rallumez.\n2. Laissez l’ampoule près du routeur et relancez la mise à jour.\n3. Essayez l’ajout manuel en mode pairing.\n4. Contactez le support Govee avec le modèle exact (H600x).\n5. Sous garantie : remplacement.', 'Causes fréquentes : Coupure réseau pendant OTA, bug firmware rare, ou flash corrompu.\n\n1. Coupez l’alimentation 10 s, rallumez.\n2. Laissez l’ampoule près du routeur et relancez la mise à jour.\n3. Essayez l’ajout manuel en mode pairing.\n4. Contactez le support Govee avec le modèle exact (H600x).\n5. Sous garantie : remplacement.', 'app Govee, réseau stable', 'app Govee, réseau stable', 'app Govee, réseau stable', 'app Govee, réseau stable', 'app Govee, réseau stable', NULL, NULL, NULL, NULL, NULL);
INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (29, 'nanoleaf-layout-invalide', 3, 5, 10, 'Layout invalide / panneaux non reconnus', 2, '15–35 min', '0 €', 0, 'Nanoleaf : disposition refusée ou panneau manquant', 'Nanoleaf : disposition refusée ou panneau manquant', 'Nanoleaf : disposition refusée ou panneau manquant', 'Nanoleaf : disposition refusée ou panneau manquant', 'Nanoleaf : disposition refusée ou panneau manquant', 'L’app ne valide pas la forme dessinée ou un panneau reste gris dans le layout.', 'L’app ne valide pas la forme dessinée ou un panneau reste gris dans le layout.', 'L’app ne valide pas la forme dessinée ou un panneau reste gris dans le layout.', 'L’app ne valide pas la forme dessinée ou un panneau reste gris dans le layout.', 'L’app ne valide pas la forme dessinée ou un panneau reste gris dans le layout.', 'Causes fréquentes : Connecteur mal enfoncé, panneau défectueux, limite de panneaux par contrôleur, ou firmware contrôleur.\n\n1. Reconnectez chaque lien jusqu’au clic.\n2. Identifiez le panneau gris en le retirant un par un.\n3. Mettez à jour le firmware du contrôleur.\n4. Respectez le max de panneaux par kit (voir boîte).\n5. Panneau mort : garantie Nanoleaf.', 'Causes fréquentes : Connecteur mal enfoncé, panneau défectueux, limite de panneaux par contrôleur, ou firmware contrôleur.\n\n1. Reconnectez chaque lien jusqu’au clic.\n2. Identifiez le panneau gris en le retirant un par un.\n3. Mettez à jour le firmware du contrôleur.\n4. Respectez le max de panneaux par kit (voir boîte).\n5. Panneau mort : garantie Nanoleaf.', 