INSERT INTO error_codes (id, slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES (30, 'nanoleaf-wifi-2g', 3, 5, 10, 'Wi-Fi connection failed', 2, '10–25 min', '0 €', 0, 'Nanoleaf : échec connexion Wi-Fi', 'Nanoleaf : échec connexion Wi-Fi', 'Nanoleaf : échec connexion Wi-Fi', 'Nanoleaf : échec connexion Wi-Fi', 'Nanoleaf : échec connexion Wi-Fi', 'Configuration Wi-Fi échoue à l’étape finale ; contrôle local uniquement.', 'Configuration Wi-Fi échoue à l’étape finale ; contrôle local uniquement.', 'Configuration Wi-Fi échoue à l’étape finale ; contrôle local uniquement.', 'Configuration Wi-Fi échoue à l’étape finale ; contrôle local uniquement.', 'Configuration Wi-Fi échoue à l’étape finale ; contrôle local uniquement.', 'Causes fréquentes : Réseau 5 GHz imposé, caractères spéciaux dans le mot de passe, ou isolation AP.\n\n1. Utilisez exclusivement le 2,4 GHz pour la config.\n2. Simplifiez temporairement le mot de passe Wi-Fi (test).\n3. Désactivez MAC filtering.\n4. Rapprochez le contrôleur du routeur.\n5. Réinitialisez le contrôleur (reset 5 s) et recommencez.', 'Causes fréquentes : Réseau 5 GHz imposé, caractères spéciaux dans le mot de passe, ou isolation AP.\n\n1. Utilisez exclusivement le 2,4 GHz pour la config.\n2. Simplifiez temporairement le mot de passe Wi-Fi (test).\n3. Désactivez MAC filtering.\n4. Rapprochez le contrôleur du routeur.\n5. Réinitialisez le contrôleur (reset 5 s) et recommencez.', 'Causes fréquentes : Réseau 5 GHz imposé, caractères spéciaux dans le mot de passe, ou isolation AP.\n\n1. Utilisez exclusivement le 2,4 GHz pour la config.\n2. Simplifiez temporairement le mot de passe Wi-Fi (test).\n3. Désactivez MAC filtering.\n4. Rapprochez le contrôleur du routeur.\n5. Réinitialisez le contrôleur (reset 5 s) et recommencez.', 'Causes fréquentes : Réseau 5 GHz imposé, caractères spéciaux dans le mot de passe, ou isolation AP.\n\n1. Utilisez exclusivement le 2,4 GHz pour la config.\n2. Simplifiez temporairement le mot de passe Wi-Fi (test).\n3. Désactivez MAC filtering.\n4. Rapprochez le contrôleur du routeur.\n5. Réinitialisez le contrôleur (reset 5 s) et recommencez.', 'Causes fréquentes : Réseau 5 GHz imposé, caractères spéciaux dans le mot de passe, ou isolation AP.\n\n1. Utilisez exclusivement le 2,4 GHz pour la config.\n2. Simplifiez temporairement le mot de passe Wi-Fi (test).\n3. Désactivez MAC filtering.\n4. Rapprochez le contrôleur du routeur.\n5. Réinitialisez le contrôleur (reset 5 s) et recommencez.', 'réseau 2,4 GHz', 'réseau 2,4 GHz', 'réseau 2,4 GHz', 'réseau 2,4 GHz', 'réseau 2,4 GHz', NULL, NULL, NULL, NULL, NULL);
